package com.bank.branchnet.service;

import java.util.ArrayList;
import java.util.List;
import java.util.PriorityQueue;
import java.util.logging.Logger;

// Prim's MST using a lazy min-heap of frontier edges.
public class BranchNetworkService {
    private static final Logger log = Logger.getLogger(BranchNetworkService.class.getName());

    public int minimumCableCost(int n, int[][] edges) {
        List<List<int[]>> adj = new ArrayList<>();
        for (int i = 0; i < n; i++) adj.add(new ArrayList<>());
        for (int[] e : edges) {                           // undirected: add both ways
            adj.get(e[0]).add(new int[]{e[1], e[2]});
            adj.get(e[1]).add(new int[]{e[0], e[2]});
        }
        boolean[] inTree = new boolean[n];
        PriorityQueue<int[]> pq = new PriorityQueue<>((a, b) -> a[0] - b[0]); // by weight
        pq.offer(new int[]{0, 0});                        // {weight, vertex}
        int total = 0, connected = 0;
        while (!pq.isEmpty() && connected < n) {
            int[] top = pq.poll();
            int w = top[0], v = top[1];
            if (inTree[v]) continue;                      // skip stale frontier edge
            inTree[v] = true;
            total += w;
            connected++;
            for (int[] e : adj.get(v)) {
                if (!inTree[e[0]]) pq.offer(new int[]{e[1], e[0]}); // push {weight, dest}
            }
        }
        final int result = total;
        log.info(() -> "Minimum cable cost to connect all branches = " + result);
        return total;
    }
}
