package com.bank.branchnet;

import com.bank.branchnet.service.BranchNetworkService;
import java.util.logging.Logger;

public class BranchNetworkApplication {
    private static final Logger log = Logger.getLogger(BranchNetworkApplication.class.getName());

    public static void main(String[] args) {
        BranchNetworkService service = new BranchNetworkService();
        // Branches 0,1,2. Leased-line monthly costs (scaled rupees).
        int[][] edges = { {0, 1, 1}, {1, 2, 2}, {0, 2, 3} };
        int cost = service.minimumCableCost(3, edges);
        log.info(() -> "Final MST cable cost = " + cost);
    }
}
